import { Box, Center, CenterProps, Flex, Spinner } from '@chakra-ui/react'
import { useState } from 'react'
import Icon, { VariantType } from './Icon'
import RefreshAnimateIcon from './RefreshAnimateIcon'

interface RefreshButtonProps extends CenterProps {
  variant?: VariantType
  handleRefresh: () => void
  isAutoRefresh?: boolean
  showAutoRefreshAnimate?: boolean // swap 特殊需求，当没输入amount 信息时，不展示自动刷新的动画效果
  refreshInterval?: number
}

export default function RefreshButton(props: RefreshButtonProps) {
  const { variant, handleRefresh, isAutoRefresh, refreshInterval, showAutoRefreshAnimate = true, ...rest } = props
  const [moveTransform, setMoveTransform] = useState(false)
  const [rotation, setRotation] = useState(0)
  const handleClick = () => {
    if (isAutoRefresh) {
      return
    }
    handleRefresh()
    setRotation(360)
    setMoveTransform(true)
    setTimeout(() => {
      setMoveTransform(false)
      setRotation(0)
    }, 1000)
  }
  return (
    // <Tooltip label={<Text fontSize="12px">Refresh</Text>} aria-label="Yield">
    <Center
      h="40px"
      w="40px"
      borderRadius="8px"
      bg="bg_secondary"
      border="1px solid"
      borderColor="border"
      cursor="pointer"
      onClick={handleClick}
      {...rest}
    >
      <Flex w="24px" h="24px" bg="checked_bg" alignItems="center" justifyContent="center" borderRadius="4px">
        {isAutoRefresh && (
          <RefreshAnimateIcon
            refreshInterval={refreshInterval || 20}
            enableClickToRefresh={true}
            handleRefresh={handleRefresh}
            showAnimate={showAutoRefreshAnimate}
          />
        )}
        {!isAutoRefresh && (
          <Box>
            {moveTransform ? (
              <Flex w="20px" h="20px" alignItems="center" justifyContent="center">
                <Spinner
                  w="16px"
                  h="16px"
                  speed="1.2s"
                  sx={{
                    color: 'text_paragraph'
                  }}
                />
              </Flex>
            ) : (
              <Box>
                <Icon xlinkHref="#icon-icon_refresh" variant="gray" />
              </Box>
            )}
          </Box>
        )}
      </Flex>
    </Center>
    // </Tooltip>
  )
}
